```python
# Define the exchange rates for the currency pairs
exchange_rates = {
    "USD": {
        "EUR": 0.8872,
        "GBP": 1.3258
    },
    "EUR": {
        "USD": 1 / 0.8872,
        "GBP": 1.15
    },
    "GBP": {
        "USD": 1 / 1.3258,
        "EUR": 0.76
    }
}

def convert_currency(amount, from_currency, to_currency):
    """
    Converts currency from one unit to another.

    :param amount: The amount of currency to convert.
    :param from_currency: The currency to convert from.
    :param to_currency: The currency to convert to.
    :return: The converted amount.
    """
    if from_currency not in exchange_rates or to_currency not in exchange_rates[from_currency]:
        raise ValueError(f"Unsupported currency pair: {from_currency} to {to_currency}")

    return amount * exchange_rates[from_currency][to_currency]

# Example usage
user_input = input("Enter the amount of USD you want to convert: ")
amount = float(user_input)
from_currency = "USD"
to_currency = input("Enter the currency to convert to (EUR or GBP): ").upper()

if to_currency == "EUR":
    converted_amount = convert_currency(amount, from_currency, to_currency)
    print(f"{amount} USD is {converted_amount:.2f} EUR")
elif to_currency == "GBP":
    converted_amount = convert_currency(amount, from_currency, to_currency)
    print(f"{amount} USD is {converted_amount:.2f} GBP")
else:
    print("Invalid currency. Please enter either 'EUR' or 'GBP'.")
```

